head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var col1Data = grid1.getColData("col1");
    for (var i = 0; i < col1Data.length; i++) {
        if (col1Data[i] == "a111") {
            grid1.setRowVisible(i, true);
        } else {
            grid1.setRowVisible(i, false);
        }
    }
};
scwin.trigger2_onclick = function(e) {
    var xmlData = WebSquare.ModelUtil.findInstanceNodes("vector/data");

    for (var i = 0; i < xmlData.length; i++) {
        // 수정된 부분: 객체 형태로 인자를 전달하며 scopeId를 추가
        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col1",
            value: "col1_" + i,
            scopeId: WebSquare.scope_obj
        });

        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col2",
            value: "col2_" + i,
            scopeId: WebSquare.scope_obj
        });

        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col3",
            value: "col3_" + i,
            scopeId: WebSquare.scope_obj
        });

        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col4",
            value: "col4_" + i,
            scopeId: WebSquare.scope_obj
        });

        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col5",
            value: "col5_" + i,
            scopeId: WebSquare.scope_obj
        });

        WebSquare.ModelUtil.setInstanceValue({
            xpath: "vector/data[@idx=" + i + "]/INFO/col6",
            value: "col6_" + i,
            scopeId: WebSquare.scope_obj
        });
    }
    debugger;
};
scwin.checkBeforeTime = function() {
    date = new Date();
    min = date.getMinutes();
    sec = date.getSeconds();
    milisec = date.getMilliseconds();
    before = (min * 60 + sec) * 1000 + milisec;
    console.log(before + " - > " + before);
}
scwin.checkAfterTime = function() {
    date = new Date();
    min = date.getMinutes();
    sec = date.getSeconds();
    milisec = date.getMilliseconds();
    after = (min * 60 + sec) * 1000 + milisec;
    console.log(after + " - > " + after);
}
scwin.compareTimeFirst = function() {
    return Math.abs(after - before) < 2000;
}
scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.checkBeforeTime()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("set", "scwin.checkAfterTime()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareTimeFirst()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('grid1_cell_10_0').innerText == 'col1_10'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
